const hrs=(at||[]).reduce((a,r)=>a+((r.check_out?new Date(r.check_out):new Date())-new Date(r.check_in))/36e5,0),late=(at||[]).reduce((a,r)=>a+r.late_min,0);
const attHist=attOn?`<h2>الحضور والانصراف</h2><div class="m" style="margin-bottom:6px">${(at||[]).length} يوم · ${hrs.toFixed(1)} ساعة · تأخير ${late} دقيقة</div>${(at||[]).map(r=>`<div class="row"><div><b>${new Date(r.check_in).toLocaleDateString("ar-EG",{weekday:"short",day:"numeric",month:"numeric"})}</b><div class="m">${hm(r.check_in)} ← ${r.check_out?hm(r.check_out):"لسه حاضر"}</div></div><div style="text-align:left">${r.late_min?`<span class="tag" style="background:var(--red);color:#fff">متأخر ${r.late_min} د</span>`:`<span class="tag">في الميعاد</span>`}${r.note?`<div class="m">${esc(r.note)}</div>`:""}</div></div>`).join("")}`:"";
const shBox=`<h2>جدول شغلي</h2>${sh?.length?[0,1,2,3,4,5,6].map(d=>{const x=sh.find(y=>y.weekday==d);return x?`<div class="row"><b>${DN[d]}</b><span>${x.is_off?"إجازة":x.start_time.slice(0,5)+" ← "+x.end_time.slice(0,5)}</span></div>`:""}).join(""):`<p class="m">لسه مفيش شيفت محدد.</p>`}${lv?.length?`<div class="m">إجازات جاية:</div>`+lv.map(l=>`<div class="row"><span>${l.from_date} ← ${l.to_date}</span><span class="m">${esc(l.reason||"")}</span></div>`).join(""):""}`;
