async function openPerms(id){const{data:p}=await sb.from("profiles").select("*").eq("id",id).single();C.pp=p;
put(`<button class="btn g s" style="margin-top:12px" onclick="V.team()">‹ رجوع</button><h1>صلاحيات ${esc(p.full_name)}</h1><p class="m">اللي مش متعلّم عليه، الموظف مش هيشوفه ولا هيقدر يوصله حتى من برّه التطبيق.</p>`+PERMS.map(x=>x[0]=="ط"?`<h2>${x[1]}</h2>`:`<label class="row" style="cursor:pointer"><span>${x[1]}</span><input type="checkbox" id="p_${x[0]}" ${can(x[0],p)?"checked":""} style="width:22px;height:22px;margin:0"></label>`).join("")+`<div class="chips" style="margin-top:12px"><button class="btn" onclick="savePerms()">حفظ الصلاحيات</button><button class="btn g" onclick="resetPerms()">رجوع للافتراضي</button></div>`)}
async function savePerms(){const o={};PERMS.forEach(x=>{if(x[0]!="ط")o[x[0]]=$("p_"+x[0]).checked});const{error}=await sb.from("profiles").update({perms:o}).eq("id",C.pp.id);error?toast(error.message):toast("تم حفظ الصلاحيات")}
async function resetPerms(){await sb.from("profiles").update({perms:{}}).eq("id",C.pp.id);toast("رجع للافتراضي");openPerms(C.pp.id)}
